def extostr(cls, e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        raise ValueError("'e' should be an instance of Exception")
    if not isinstance(max_level, int) or max_level < 0:
        raise ValueError("'max_level' should be a non-negative integer")
    if not isinstance(max_path_level, int) or max_path_level < 0:
        raise ValueError("'max_path_level' should be a non-negative integer")

    stack = cls._get_stack_info(sys.exc_info()[2], max_level)
    path = cls._get_path_info(stack, max_path_level)

    msg = "Exception type: {0}\nException message: {1}\n".format(type(e), str(e))

    if len(stack) > 0:
        msg += "Stack:\n"
        for level, frame in enumerate(stack):
            msg += "\t{0} from {1} line {2} in {3}\n".format(level, frame[0], frame[1], frame[2])

    if len(path) > 0:
        msg += "Path:\n"
        for level, frame in enumerate(path):
            msg += "\t{0} from {1} line {2} in {3}\n".format(level, frame[0], frame[1], frame[2])

    return msg

