def query_utilities(interfaces: list[Interface], context: IContext) -> list[tuple[IUtility, list[Interface]]]:
    """Return a sequence of tuples containing a utility and its implemented
    interfaces.

    The keyword arguments define the interfaces sought.

    The order of the sequence is the order of construction of each utility.
    """
    utilities: list[tuple[IUtility, list[Interface]]] = []
    for interface in interfaces:
        for utility in context.lookup(interface):
            utility_interfaces = []
            for name, adapter in utility.adapters.items():
                if adapter.provided == interface:
                    utility_interfaces.append(name)
            utilities.append((utility, utility_interfaces))
    return utilities

