    # Step 1: Create a dictionary to keep track of the bases
    bases = {}
    for cls in classes:
        if cls in bases:
            continue
        bases[cls] = set()
        for parent in cls.__bases__:
            if parent not in bases:
                bases[parent] = set()
            bases[parent].add(cls)
