    sorted_bases = sorted(bases.items(), key=lambda x: len(x[1]))
    # Step 3: Iteratively merge the bases until only one is left
    while len(sorted_bases) > 1:
        merged_bases = set()
        for i in range(len(sorted_bases)):
            if i == len(sorted_bases) - 1:
                break
            base1, children1 = sorted_bases[i]
            base2, children2 = sorted_bases[i + 1]
            if children1.issubset(children2):
                merged_bases.add(base1)
            elif children2.issubset(children1):
                merged_bases.add(base2)
        # Step 4: Remove the merged bases from the sorted bases list
        for base in merged_bases:
            sorted_bases.remove(base)
    # Step 5: Return the last base in the sorted bases list
    return sorted_bases[0][0]

