    elif not _KEY_REGEX.match(key):
        return f"Label key '{key}' does not match the regex {_KEY_REGEX.pattern}"

def _validate_value(value):
    if not isinstance(value, (str, bytes)):
        return 'expected string or bytes-like object'

def _validate_labels(labels):
    messages = []
    for key, value in labels.items():
        if not isinstance(key, str):
            messages.append({key: 'expected string or bytes-like object'})
        if not isinstance(value, (str, bytes)):
            messages.append({value: 'expected string or bytes-like object'})
        if not re.match(LABEL_KEY_REGEX, key):
            messages.append({key: f"Label key '{key}' does not match the regex {LABEL_KEY_REGEX}"})
        if not re.match(LABEL_VALUE_REGEX, value):
            messages.append({value: f"Label value '{value}' does not match the regex {LABEL_VALUE_REGEX}"})
    if messages:
        raise ValidationError(messages)

