def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: The default observer schema for the given application, with the format
            described in the :ref:`krake.data.kubernetes.Application` class.
    """
    default_observer_schema = {}
    for resource in app.spec.manifest:
        if resource.name not in app.spec.observer.schema:
            default_observer_schema[resource.name] = {
                "resources": set(resource.names),
                "readiness": "Present",
                "behavior": "Finalizing"
            }
    return default_observer_schema

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
	"""
	Convert the SQL query to use the out-style parameters instead of the
	in-style parameters.

	:param sql: The SQL query.
	:param many_params: Contains each set of in-style parameters.
	:return: A tuple containing the formatted SQL query and a list of each set of converted out-style parameters.
	"""
	if not self.in_style:
		return sql, []

	out_params = []
	for params in many_params:
		if isinstance(params, dict):
			out_params.append({':{}{}'.format(self.in_style.prefix, name): value for name, value in params.items()})
		elif isinstance(params, (list, tuple)):
			out_params.append({':{}{}'.format(self.in_style.prefix, index + 1): value for index, value in enumerate(params)})

	offset = 0
	for i, match in enumerate(re.finditer(self._in_style_pattern, sql)):
		start, end = match.span()
		if i >= len(out_params):
			break

		param_names = match.group(1).split(', ')
		param_values = out_params[i]
		for j, param_name in enumerate(param_names):
			if param_name not in param_values:
				continue

			param_value = param_values[param_name]
			if isinstance(param_value, (list, tuple)):
				param_value = ', '.join(param_value)

			sql = sql[:start + offset] + param_value + sql[end + offset:]
			offset += len(param_value) - (end - start)

