def _fromutc(self, dt):
    if not dt.tzinfo:
        raise ValueError("Expected a timezone-aware datetime object, but got a naive datetime instead")

    # Determine the target timezone offset from UTC
    offset = self.tzinfo.utcoffset(dt)
    if offset is None:
        raise ValueError("Target timezone has no defined offset from UTC")

    # Calculate the target datetime using the offset
    target_dt = dt + offset

    # Determine whether the target datetime is ambiguous
    is_ambiguous = target_dt.tzinfo.dst(target_dt) is not None

    # Return a timezone-aware datetime object in the target timezone
    return datetime_tz(target_dt, tzinfo=self.tzinfo, is_ambiguous=is_ambiguous)

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    normalized_values = {}
    for attr, value in self.__dict__.items():
        if not isinstance(value, (int, float)):
            continue
        normalized_value = self._normalize_value(attr, value)
        normalized_values[attr] = normalized_value
    return self.__class__(normalized_values)

def _normalize_value(self, attr, value):
    if attr in ('years', 'months', 'days'):
        return int(value)
    elif attr in ('hours', 'minutes', 'seconds', 'microseconds'):
        return value * SECONDS_PER_MINUTE
    elif attr == 'weeks':
        return value * DAYS_PER_WEEK
    elif attr == 'year':
        return self.year = _normalize_year(value)
    elif attr == 'month':
        return self.month = _normalize_month(value)
    elif attr == 'day':
        return self.day = _normalize_day(value)
    else:
        raise ValueError("Unsupported attribute %r for normalization" % attr)

