def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding and len(alphabet) < padding:
        raise ValueError("The length of the alphabet must be greater than or equal to the padding value.")
    if number == 0:
        return "0"
    is_negative = number < 0
    if is_negative:
        number = -number
    result = []
    while number > 0:
        digit = number % len(alphabet)
        number //= len(alphabet)
        result.append(alphabet[digit])
    if is_negative:
        result.append("-")
    if padding:
        result.extend(["0"] * (padding - len(result)))
    return "".join(reversed(result))

