    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Join the temporary path with the filename
    if filename:
        tmp_file_path = os.path.join(tmp_path, filename)
    else:
        tmp_file_path = tmp_path

    # Extract the archive
    try:
        with tarfile.open(archive_path) as archive:
            archive.extractall(tmp_file_path)
    except tarfile.TarError as e:
        raise tarfile.TarError("Error extracting archive: {}".format(e))

    # Return the file repo URL
    return "file://{}".format(tmp_file_path)
