    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    todo = set(graph.subjects(prop, None))
    done = set()
    if roots is None:
        roots = set()
    while todo:
        node = todo.pop()
        if node in done:
            continue
        done.add(node)
        for child in graph.subjects(prop, node):
            if child not in done:
                todo.add(child)
        if not todo:
            roots.add(node)
    return roots

