def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks out of bounds: 0 <= ticks < 86400000000000")
    ms = ticks // 1000000
    us = ticks % 1000000
    h, m, s = ms // 3600000, ms % 3600000 // 60000, ms % 60000 // 1000
    return cls(h, m, s, us, tz)

def from_ticks(cls, ticks, tz=None):
    if not 0 <= ticks < 86400000000000:
        raise ValueError("Ticks must be between 0 and 86399999999999")
    hours, remainder = divmod(ticks, 3600000000000)
    minutes, remainder = divmod(remainder, 60000000000)
    seconds, nanoseconds = divmod(remainder, 1000000000)
    return cls(hours, minutes, seconds, nanoseconds, tzinfo=tz)

