def set_cut_chars(self, before: bytes, after: bytes) -> None:
    """Set the bytes used to delimit slice points.

    Args:
        before: Split file before these delimiters.
        after: Split file after these delimiters.
    """

    if not isinstance(before, bytes):
        raise TypeError("before must be a bytes-like object")
    if not isinstance(after, bytes):
        raise TypeError("after must be a bytes-like object")

    self._cut_chars_before = before
    self._cut_chars_after = after

def split_bytes(self, data: bytes) -> __iterator[bytes]:
    """Split a bytes object into chunks separated by the cut characters.

    Args:
        data: The bytes object to split.

    Yields:
        __iterator[bytes]: The chunks of the bytes object, separated by the cut characters.
    """

    if not isinstance(data, bytes):
        raise TypeError("data must be a bytes-like object")

    cut_chars_before = self._cut_chars_before
    cut_chars_after = self._cut_chars_after

    start = 0
    while start < len(data):
        end = data.find(cut_chars_before, start)
        if end == -1:
            end = len(data)
        chunk = data[start:end]
        yield chunk
        start = end + len(cut_chars_before)

        if end < len(data):
            end = data.find(cut_chars_after, end)
            if end == -1:
                end = len(data)
            chunk = data[start:end]
            yield chunk
            start = end + len(cut_chars_after)

    yield data[start:]

