def parse_diaspora_webfinger(document):
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
    except json.JSONDecodeError:
        data = xml.etree.ElementTree.fromstring(document)
        if data.tag != "{urn:xmpp:extdisco:2}extdisco":
            raise ValueError("Invalid XRD document")
        data = data.find(".//{http://docs.oasis-open.org/ws-sx/ws-trust/200512/}KeyInfo")
        if data is None:
            raise ValueError("No KeyInfo element found in XRD document")
        return {"hcard_url": data.attrib["url"], "public_key": data.attrib["cert"]}
    if not data.get("Link") or data.get("Link").__class__ != list:
        raise ValueError("Invalid Diaspora webfinger document")
    link_url = data.get("Link")[0].get("href")
    if not link_url.startswith(DiasporaConstants.hcard_url_prefix):
        raise ValueError("Invalid hCard URL")
    return {"hcard_url": link_url}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        if document.startswith("{"):
            return json.loads(document)
        else:
            tree = etree.fromstring(document)
            xrd = XRD(tree)
            return {
                "subject": xrd.get("Subject"),
                "aliases": [link.get("href") for link in xrd.findall(".//Link[@rel='http://schemas.google.com/g/2010#updates-from']")],
                "links": [link.get("href") for link in xrd.findall(".//Link[@rel='http://schemas.google.com/g/2010#updates-from']")],
                "properties": {prop.get("name"): prop.get("value") for prop in xrd.findall(".//Property")}
            }
    except Exception as e:
        raise ValueError(f"Failed to parse Diaspora webfinger document: {document}") from e

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON first
        json_data = json.loads(document)
        return {
            "hcard_url": json_data["links"][-1]["href"],
            "handle": json_data["properties"]["https://diaspora.org/ns/handle"],
            "public_key": json_data["properties"]["https://diaspora.org/ns/publicKey"],
        }
    except ValueError:
        # If that fails, try to parse as XRD
        xrd_xml = xml.etree.ElementTree.fromstring(document)
        url = xrd_xml.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject").text
        expires = xrd_xml.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Expires").text
        if expires:
            expires = datetime.strptime(expires, "%Y-%m-%dT%H:%M:%SZ")
        jabber_id = None
        for xrd_property in xrd_xml.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Property"):
            if xrd_property.attrib["type"] == "http://www.iana.org/assignments/uri-schemes/xmpp/jid":
                jabber_id = xrd_property.text
                break
        return {
            "hcard_url": url,
            "jabber_id": jabber_id,
            "expires": expires,
        }

def parse_diaspora_webfinger(document: str) -> Dict:
