def validate_from_content(spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content is missing")

    try:
        spec_dict = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Unable to parse spec content: {e}")

    mandatory_fields = ['name', 'type', 'version']
    for field in mandatory_fields:
        if field not in spec_dict:
            raise IRValidatorException(f"'{field}' field is missing in spec file")

    return spec_dict

def validate_from_content(spec_content=None):
