    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if not spec_content:
        raise IRValidatorException("Spec content is empty")
    spec_dict = yaml.safe_load(spec_content)
    if not spec_dict:
        raise IRValidatorException("Spec content is empty")

    required_fields = ["name", "type", "version"]

    errors = []
    for field in required_fields:
        if field not in spec_dict:
            errors.append(f"Missing {field} field in spec")

    if errors:
        raise IRValidatorException(", ".join(errors))

    return spec_dict

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except OSError:
        raise IRValidatorException(f"Could not open file {yaml_file}")
    except yaml.YAMLError:
        raise IRValidatorException(f"Could not load YAML data from {yaml_file}")

    try:
        cls.validate(data)
    except IRValidatorException:
        raise IRValidatorException(f"File {yaml_file} has missing or invalid fields")

    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise ValueError("'yaml_file' argument must be supplied")

    try:
        yaml_data = yaml.load(open(yaml_file, 'r'))
    except ScannerError as se:
        raise IRValidationException(
            "There was a problem parsing the YAML file.  "
            "This can be because you forgot spaces after colons in your YAML file for instance.  "
            "Diagnostic information follows.\n" + str(se)
        )
    except Exception as e:
        raise IRValidationException(
            "There was a problem loading the YAML file.\n{}: {}".format(type(e), e.__str__())
        )

    if not all(field in yaml_data for field in cls.REQUIRED_FIELDS):
        missing_fields = [field for field in cls.REQUIRED_FIELDS if field not in yaml_data]
        raise IRValidationException("Required fields are missing from YAML file: {}".format(missing_fields))

    return yaml_data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' in parser_dict:
        include_spec = parser_dict['include']
        if isinstance(include_spec, six.string_types):
            include_spec = {'behavior': include_spec}
        include_behavior = include_spec['behavior']
        grouped_options = self._parse_section_options(include_spec['options']).unwrap()
        if include_behavior == 'extend':
            parser_dict['options'] = parser_dict.get('options', []) + grouped_options
        elif include_behavior == 'prepend':
            parser_dict['options'] = grouped_options + parser_dict.get('options', [])
        else:
            raise KeyError("Unrecognized include behavior: %s" % include_behavior)
    return parser_dict

